function wrapLines(s,x,y,size){const words=String(s).split(' '),max=Math.floor(900/size),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max&&lines.at(-1))lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines.map((v,i)=>`<tspan x="${x}" y="${y+i*(size+4)}">${esc(v)}</tspan>`).join('');}
import{experimentOptions,experimentResult,outputLabel}from './mag1-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const txt=(x,y,s,size=16)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#f5f2eb" text-anchor="middle">${wrapLines(s,x,y,size)}</text>`;const line=(x,y,a,b,c='#abcfc8',w=2)=>`<path d="M${x} ${y}L${a} ${b}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const magnet=(x,y,w=160,reverse=false)=>`<rect x="${x}" y="${y}" width="${w}" height="55" rx="8" fill="#d58b7a"/><path d="M${x+w/2} ${y} H${x+w-8} Q${x+w} ${y} ${x+w} ${y+8} V${y+47} Q${x+w} ${y+55} ${x+w-8} ${y+55} H${x+w/2}Z" fill="#6d9eab"/>${txt(x+w*.25,y+34,reverse?'S':'N',20)}${txt(x+w*.75,y+34,reverse?'N':'S',20)}`;
const coil=(x,y,n=7,w=115)=>Array.from({length:n},(_,i)=>`<ellipse cx="${x+i*w/(n-1)}" cy="${y}" rx="12" ry="47" fill="none" stroke="#e6bd88" stroke-width="3"/>`).join('');
const arrow=(x,y,a,b,c='#ef947e')=>line(x,y,a,b,c,3)+`<path d="M${a-9*Math.cos(Math.atan2(b-y,a-x)-.5)} ${b-9*Math.sin(Math.atan2(b-y,a-x)-.5)}L${a} ${b}L${a-9*Math.cos(Math.atan2(b-y,a-x)+.5)} ${b-9*Math.sin(Math.atan2(b-y,a-x)+.5)}" stroke="${c}" fill="none" stroke-width="3"/>`;
export function magneticFigure({kind='fields',movie=false,progress=.3,a,b,revealed=false}={}){const k=kind.split('-')[0],o=experimentOptions[k]||experimentOptions.fields,A=String(a??o.a[0][0]),B=String(b??o.b[0][0]),p=movie?Math.max(0,Math.min(1,progress)):.3,phase=Math.sin(2*Math.PI*p);let s='',title='',note='';
if(k==='poles'){s+=magnet(65,210,150,A==='N')+(B==='iron'?`<rect x="350" y="210" width="140" height="55" rx="8" fill="#a6b4bf"/>`+txt(420,244,'Iron'):magnet(350,210,140,B==='S'))+txt(280,330,'Read the two facing ends, not just bar colours');title='Like poles repel; unlike poles attract';note='Iron is attracted by induced magnetism · forces are not calibrated';}
else if(k==='fields'){let rev=B==='reverse';s+=magnet(200,215,160,rev);for(let i=0;i<4;i++){let h=45+i*28;s+=`<path d="M215 215 C120 ${215-h} 440 ${215-h} 345 215 M215 270 C120 ${270+h} 440 ${270+h} 345 270" stroke="#a7cfc7" stroke-width="1.5" fill="none"/>`;}s+=arrow(rev?310:250,140,rev?250:310,140)+txt(280,110,'External direction: north → south')+`<circle cx="${A==='left'?115:445}" cy="242" r="25" fill="#223f55" stroke="#bcd2cc"/>`+(B==='normal'?arrow(A==='left'?130:460,242,A==='left'?100:430,242):arrow(A==='left'?100:430,242,A==='left'?130:460,242));title='Map a field with a plotting compass';note='Line spacing shows relative strength · field lines are representations';}
else if(k==='electromagnets'){s+=coil(230,220,8,130);if(B==='iron')s+=`<rect x="210" y="211" width="170" height="18" rx="4" fill="#a4b6c1" opacity=".7"/>`;let visible=movie?p:A==='on'?1:0;s+=`<g opacity="${visible}">`;for(let i=0;i<3;i++)s+=arrow(220,200+i*20,380,200+i*20,'#a9d2cb');s+=txt(205,290,'S',16)+txt(390,290,'N',16);s+='</g>';s+=txt(295,310,'Solenoid: fields from turns reinforce')+`<circle cx="110" cy="200" r="24" fill="none" stroke="#a9d2cb"/><circle cx="110" cy="200" r="5" fill="#ef947e"/>`+txt(110,130,'Separate wire example',11)+txt(110,150,'Current out',12)+arrow(110,176,90,185)+txt(110,255,'Field anticlockwise',12);title='Current creates a field · iron strengthens the coil field';note='Inside field approximately uniform · core saturation/real permeability omitted';}
else if(k==='motoreffect'){s+=magnet(70,185,100,true)+magnet(395,185,100,true)+arrow(190,215,375,215,'#a9d2cb')+`<circle cx="280" cy="215" r="18" fill="#233e53" stroke="#e8c688"/><circle cx="280" cy="215" r="5" fill="#ef947e"/>`+arrow(280,195,280,195-Math.min(100,Number(A)*Number(B)*50))+txt(280,90,'Force ↑')+txt(280,270,'Current out of page •')+txt(280,315,'Field right →')+txt(280,365,`B=${A} T · I=${B} A · l=0.5 m`);title='Fleming: field, conventional current and force perpendicular';note='Displayed orientation is the reference perpendicular case';}
else if(['motors','generators'].includes(k)){let motorSign=k==='motors'&&A!==B?-1:1,angle=motorSign*(movie?p*360:35),sx=90*Math.sin(angle*Math.PI/180),rev=k==='motors'?A!=='reverse':true;s+=magnet(65,190,110,rev)+magnet(390,190,110,rev)+arrow(rev?180:380,215,rev?380:180,215,'#a9d2cb')+`<path d="M${280-sx} 150 L${280+sx} 175 V300 L${280-sx} 275Z" fill="#ddc18d" fill-opacity=".14" stroke="#e7c38c" stroke-width="4"/>`+line(280,145,280,340,'#afc9c6',2)+(k==='generators'&&A==='alternator'?`<ellipse cx="280" cy="320" rx="30" ry="10" fill="none" stroke="#e8c18d" stroke-width="5"/><ellipse cx="280" cy="339" rx="30" ry="10" fill="none" stroke="#b6d8d0" stroke-width="5"/>`:`<path d="M250 ${k==='generators'?325:350} A30 12 0 0 1 278 ${k==='generators'?325:350} M283 ${k==='generators'?325:350} A30 12 0 0 1 310 ${k==='generators'?325:350}" stroke="#e8c18d" stroke-width="7" fill="none"/>`)+txt(280,k==='motors'?395:90,k==='motors'?(p<.5?'Coil current orientation1':'After half-turn: commutator reverses coil current'):(A==='alternator'?'Slip rings: AC':'Split ring: pulsating DC'),13);title=k==='motors'?'Opposite side forces turn the coil':'Mechanical motion induces an electrical output';note='Rotation is prescribed for explanation, not a load/speed solution';if(k==='motors')s+=arrow(280-sx,220,280-sx,220-motorSign*(sx>=0?55:-55))+arrow(280+sx,220,280+sx,220+motorSign*(sx>=0?55:-55));if(k==='generators'){let pts=Array.from({length:81},(_,i)=>`${170+i*2.75},${380-25*(A==='alternator'?Math.sin(i/80*2*Math.PI):Math.abs(Math.sin(i/80*2*Math.PI)))}`).join(' ');let cp=movie?p:B==='negative'?.75:.25;s+=line(170,380,390,380,'#7899a6',1)+`<polyline points="${pts}" fill="none" stroke="#ef947e" stroke-width="2"/><circle cx="${170+220*cp}" cy="${380-25*(A==='alternator'?Math.sin(cp*2*Math.PI):Math.abs(Math.sin(cp*2*Math.PI)))}" r="5" fill="#eac784"/>`;}}
else if(['speakers','microphones'].includes(k)){let dx=movie?15*phase:0;s+=magnet(80,195,120)+coil(230+dx,225,6,65)+`<path d="M${305+dx} 195 L${365+dx} 140 V310 L${305+dx} 255Z" stroke="#b9d8ce" stroke-width="4" fill="#8aaeb2" fill-opacity=".3"/>`;for(let i=0;i<3;i++)s+=`<path d="M${395+i*25} 155 Q${425+i*25+dx} 225 ${395+i*25} 295" fill="none" stroke="#ed947e" opacity="${.7-i*.15}"/>`;title=k==='speakers'?'Current → motor force → cone vibration → sound':'Sound → diaphragm motion → induced signal';s+=txt(280,365,'Movement and pressure variations shown at slowed playback');note='Frequency response, amplitude and clinical hearing are not calibrated';}
else if(k==='induction'){let z=movie?(p<.5?p*2:(1-p)*2):.5;s+=magnet(50+100*z,200,140,B==='N')+coil(315,225,9,115)+`<rect x="310" y="335" width="120" height="45" rx="10" fill="#223f55" stroke="#a9cfc9"/>`+txt(370,364,movie?(p<.5?'+ pulse':'− pulse'):'Detector')+txt(280,125,A==='in'?'Pole enters coil':'Pole leaves coil');title='Change field relationship → induced potential difference';note='North entering is positive by the stated wiring reference · no voltage calibration';}
else if(k==='transformers'){s+=`<path d="M150 130 H410 V320 H150Z M190 170 V280 H370 V170Z" fill="#8299a6" fill-rule="evenodd" opacity=".55"/>`+coil(128,225,6,45)+coil(388,225,Number(A)>100?10:5,45)+`<g opacity="${.2+.8*Math.abs(phase)}">`+arrow(phase>=0?240:320,150,phase>=0?320:240,150,phase>=0?'#ef947e':'#a9ceca')+'</g>'+txt(135,365,'Primary100 turns',14)+txt(420,365,'Secondary'+A+' turns',14)+txt(280,105,`${12*Number(B)} V AC primary`);title='Changing common core field links two separate coils';note='Iron easily magnetised · ideal ratio/power model omits losses';}
if(a&&b&&revealed)s+=txt(280,460,outputLabel(k,experimentResult(k,A,B).value),14);
return `<svg class="shell-diagram mag1-diagram" viewBox="0 0 560 480" role="img" aria-label="${esc(k+' labelled magnetic model'+(revealed?' with revealed output':''))}">${txt(280,50,title,15)}${s}${txt(280,425,note,12)}</svg>`;}
